import numpy as np, json
from scipy import ndimage
def comps(g):
    g=np.array(g); res=[]
    for c in [x for x in np.unique(g) if x]:
        lab,n=ndimage.label(g==c)
        for i in range(1,n+1):
            ys,xs=np.where(lab==i)
            res.append((c,(ys.min(),xs.min()),(g[ys.min():ys.max()+1,xs.min():xs.max()+1]==c).astype(int)))
    return res

