        hs=[m.shape[0] for m in sh]; H=sum(hs)+len(sh)-1
        band=np.zeros((H,mw),int)
        r=H
        for m in sh:
            r-=m.shape[0]
            band[r:r+m.shape[0], :m.shape[1]]=m
            r-=1
        return band
    BL=band(L,True); BR=band(R,False)
